<script setup lang="ts">
import {computed,ref} from 'vue';
import GameAnchors from './GameAnchors.vue';
import {createOriginalRecognition} from '../recognition/original-events';
import {wispRatings} from '../game/metatft-wisps';
import {dataset} from '../game/tft-data';
import {shopOverlayLayout} from '../game/shop-overlay-layout';
import type {ReaderStatus} from '../recognition/status';
const reducer=createOriginalRecognition(),view=ref(reducer.view());
const layout=shopOverlayLayout(1280,720),round=ref(1);
const choices=['S','A','B','C','D'].map(tier=>Object.keys(wispRatings.ratings).find(id=>wispRatings.ratings[id]===tier)!);
const packet=(key:string,value:unknown)=>JSON.stringify({type:'info',category:'game_info',key,value:JSON.stringify(value)});
function shop(id:string){reducer.accept(packet('tft_shop',['DA_18_Rakan','DA_18_Kayle','DA_18_Leona','DA_18_Varus',id].map(name=>({name}))));view.value=reducer.view();}
function nextRound(){round.value++;reducer.accept(packet('tft_round',{type:'PVP',stage:'2-'+round.value}));view.value=reducer.view();}
function visible(){reducer.accept(JSON.stringify({type:'event',key:'tft_shop_visible',value:String(view.value.shopVisible===false)}));view.value=reducer.view();}
reducer.accept(packet('tft_round',{type:'PVP',stage:'2-1'}));shop(choices[0]);
const status=computed<ReaderStatus>(()=>({phase:'receiving',message:'仙灵叠加预览',testMode:false,transport:'original-native',frames:1,lastFrameAt:Date.now(),cards:view.value}));
</script>
<template><div class="shop-design"><header><strong>仙灵评级定位</strong><span>示例数据 · 复用实际原生事件解析与叠加组件</span><button v-for="(id,i) in choices" :key="id" @click="shop(id)">{{ ['S','A','B','C','D'][i] }}</button><button @click="shop('Sold')">购买后</button><button @click="nextRound">下一回合</button><button @click="visible">{{ view.shopVisible===false?'显示商店':'隐藏商店' }}</button></header><div class="game-canvas"><div class="board-placeholder"><span>2-{{ round }}</span><i v-for="n in 28" :key="n"/></div><div v-if="view.shopVisible!==false" class="preview-shop" :style="layout"><div v-for="n in 5" :key="n" class="shop-card" :class="{wisp:view.shop[n-1]?.kind==='wisp'}"><template v-if="view.shop[n-1]"><svg v-if="view.shop[n-1]!.kind==='wisp'" viewBox="0 0 64 64"><path d="M32 57C9 50 7 27 19 10c3 16 17 16 18 4 13 14 20 35-5 43Z"/><circle cx="30" cy="36" r="11"/><path d="M30 28v10m-4-5h8"/></svg><img v-else :src="dataset.characterById(view.shop[n-1]!.id)?.image_path" :alt="view.shop[n-1]!.name"/><strong>{{ view.shop[n-1]!.name }}</strong></template><span v-else>空槽</span></div></div><GameAnchors embedded :status="status" :width="1280" :height="720" :highlighted-slots="[0,3]"/></div></div></template>
<style scoped>.shop-design{min-height:100vh;background:#0e141c;color:#bfc8ce;font:12px/1.5 "Microsoft YaHei",sans-serif;overflow:auto;padding:25px 30px}.shop-design>header{display:flex;align-items:center;gap:8px;margin-bottom:20px;flex-wrap:wrap}.shop-design>header strong{color:#d4c49d;font-size:14px}.shop-design>header span{font-size:10px;color:#617183;margin-right:auto}.shop-design button{font-size:10px;padding:5px 9px;border-color:#34404d;background:#1b2530;color:#9babb9}.game-canvas{position:relative;aspect-ratio:16/9;width:100%;max-width:1280px;margin:auto;background:radial-gradient(ellipse at 50% 35%,#263a33,#101a22 70%);border:1px solid #2a3942;overflow:hidden;border-radius:5px}.board-placeholder{position:absolute;left:26%;top:12%;width:49%;height:45%;display:grid;grid-template-columns:repeat(7,1fr);gap:7px;transform:perspective(900px) rotateX(25deg);opacity:.25}.board-placeholder i{background:#65807320;border:1px solid #72937826;clip-path:polygon(50% 0,100% 25%,100% 75%,50% 100%,0 75%,0 25%)}.board-placeholder>span{position:absolute;top:-30%;left:45%;color:#98a18d;font-size:20px}.preview-shop{position:absolute;display:grid;grid-template-columns:repeat(5,1fr);gap:8px}.shop-card{position:relative;overflow:hidden;background:#161b24;border:1px solid #675c43;border-radius:3px;display:grid;place-items:center}.shop-card img{width:100%;height:100%;object-fit:cover;filter:brightness(.72)}.shop-card strong{position:absolute;bottom:0;left:0;right:0;text-align:center;font-size:clamp(8px,1vw,12px);background:#171a23ef;padding:3px 1px;color:#c5cac7;font-weight:400}.shop-card.wisp{background:radial-gradient(circle at 50% 40%,#806340,#3e3427 70%)}.shop-card svg{width:65%;height:70%;fill:#8e9b69;stroke:#c3bb8a;stroke-width:2}.shop-card.wisp strong{background:#5a472a;color:#e1d6af}.shop-card>span{font-size:10px;color:#485664}</style>
